function computeStats(user) {
  const one = (sql) => db.prepare(sql).get();
  if (user.role === 'employee') {
    const base = (st) => db.prepare('SELECT COUNT(*) AS n, COALESCE(SUM(amount),0) AS s FROM reimbursements WHERE applicant_id = ?').get(user.id);
    const all = one(`SELECT
      SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) AS pending,
      SUM(CASE WHEN status='approved' THEN 1 ELSE 0 END) AS approved,
      SUM(CASE WHEN status='rejected' THEN 1 ELSE 0 END) AS rejected,
      SUM(CASE WHEN status='paid' THEN 1 ELSE 0 END) AS paid,
      SUM(CASE WHEN status='withdrawn' THEN 1 ELSE 0 END) AS withdrawn,
      COUNT(*) AS total`).all;
    const get = (st) => db.prepare('SELECT COUNT(*) AS n, COALESCE(SUM(amount),0) AS s FROM reimbursements WHERE applicant_id = ? AND status = ?').get(user.id, st);
    return {
      pending: get('pending'), approved: get('approved'), rejected: get('rejected'),
      paid: get('paid'), total: get2total(), // see below
    };
  }
  // finance / cashier
  const g = (st) => db.prepare('SELECT COUNT(*) AS n, COALESCE(SUM(amount),0) AS s FROM reimbursements WHERE status = ?').get(st);
  return {
    pending: g('pending'), approved: g('approved'), rejected: g('rejected'),
    paid: g('paid'), withdrawn: g('withdrawn'),
    total: db.prepare('SELECT COUNT(*) AS n FROM reimbursements').get(),
  };
}

