{"content": "'use strict';
// 端到端 API 冒烟测试（仅为开发验证，测试后删除）
const BASE = 'http://127.0.0.1:3300';
let pass = 0, fail = 0;
function ok(cond, msg) { if (cond) { pass++; console.log('  ✓', msg); } else { fail++; console.log('  ✗ FAIL:', msg); } }
async function api(method, path, { token, body } = {}) {
  const headers = {};
  if (token) headers['Authorization'] = 'Bearer ' + token;
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  const res = await fetch(BASE + path, { method, headers, body: body !== undefined ? JSON.stringify(body) : undefined });
  const txt = await res.text();
  let json; try { json = txt ? JSON.parse(txt) : {}; } catch { json = { _raw: txt }; }
  return { status: res.status, json };
}
const PNG = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==';

(async () => {
  console.log('== 认证 ==');
  const login = await api('POST', '/api/login', { body: { username: 'zhangwei', password: '123456' } });
  ok(login.status === 200 && login.json.token, '员工登录成功');
  const emp = login.json.user.role;
  ok(emp === 'employee', '角色为 employee');
  const wToken = login.json.token;

  const badLogin = await api('POST', '/api/login', { body: { username: 'zhangwei', password: 'x' } });
  ok(badLogin.status === 401, '错误密码被拒绝');

  // 员工 B
  const linaLogin = await api('POST', '/api/login', { body: { username: 'lina', password: '123456' } });
  const lToken = linaLogin.json.token;
  const finLogin = await api('POST', '/api/login', { body: { username: 'finance', password: '123456' } });
  const fToken = finLogin.json.token;
  const cashLogin = await api('POST', '/api/login', { body: { username: 'cashier', password: '123456' } });
  const cToken = cashLogin.json.token;

  console.log('== 员工发起 ==');
  const created = await api('POST', '/api/reimbursements', { token: wToken, body: { amount: 580.5, invoiceContent: '出差高铁票', reason: '赴上海客户现场支持', invoiceImage: PNG } });
  ok(created.status === 200 && created.json.item.status === 'pending', '员工提交申请成功，状态 pending');
  const id = created.json.item.id;

  const badAmount = await api('POST', '/api/reimbursements', { token: wToken, body: { amount: -5, invoiceContent: 'x', reason: 'y', invoiceImage: PNG } });
  ok(badAmount.status === 400, '负金额被拒绝');
  const badImg = await api('POST', '/api/reimbursements', { token: wToken, body: { amount: 10, invoiceContent: 'x', reason: 'y', invoiceImage: 'data:image/png;base64,aGVsbG8=' } });
  ok(badImg.status === 400, '伪造图片内容被拒绝');
  const noImg = await api('POST', '/api/reimbursements', { token: wToken, body: { amount: 10, invoiceContent: 'x', reason: 'y' } });
  ok(noImg.status === 400, '缺少图片被拒绝');

  console.log('== 越权 ==');
  const empSeeAll = await api('GET', '/api/reimbursements', { token: wToken });
  ok(empSeeAll.json.items.every(i => i.applicant.name === '张伟'), '员工只能看到自己的申请');
  const linaSeeW = await api('GET', '/api/reimbursements/' + id, { token: lToken });
  ok(linaSeeW.status === 403, '员工乙无法查看员工甲的申请');

  console.log('== 财务审核 ==');
  const refuseApproveByEmp = await api('POST', `/api/reimbursements/${id}/approve`, { token: wToken });
  ok(refuseApproveByEmp.status === 403, '员工无权审核');
  const approve = await api('POST', `/api/reimbursements/${id}/approve`, { token: fToken });
  ok(approve.status === 200 && approve.json.item.status === 'approved', '财务审核通过');
  const reapprove = await api('POST', `/api/reimbursements/${id}/approve`, { token: fToken });
  ok(reapprove.status === 400, '重复审核被拒绝（幂等）');

  console.log('== 出纳打款 ==');
  const payByFinance = await api('POST', `/api/reimbursements/${id}/pay`, { token: fToken });
  ok(payByFinance.status === 403, '财务无权打款');
  const pay = await api('POST', `/api/reimbursements/${id}/pay`, { token: cToken });
  ok(pay.status === 200 && pay.json.item.status === 'paid', '出纳打款成功');
  const repay = await api('POST', `/api/reimbursements/${id}/pay`, { token: cToken });
  ok(repay.status === 400, '重复打款被拒绝（幂等）');

  console.log('== 下游驳回/撤回流程 ==');
  const created2 = await api('POST', '/api/reimbursements', { token: wToken, body: { amount: 120, invoiceContent: '办公用品', reason: '购买打印纸', invoiceImage: PNG } });
  const id2 = created2.json.item.id;
  const rejectNoNote = await api('POST', `/api/reimbursements/${id2}/reject`, { token: fToken, body: {} });
  ok(rejectNoNote.status === 400, '驳回未填写原因被拒绝');
  const reject = await api('POST', `/api/reimbursements/${id2}/reject`, { token: fToken, body: { note: '发票抬头不符' } });
  ok(reject.json.item.status === 'rejected', '驳回并记录原因');
  const resubmit = await api('PUT', `/api/reimbursements/${id2}`, { token: wToken, body: { amount: 120, invoiceContent: '办公用品', reason: '购买打印纸（已更正抬头）', invoiceImage: PNG } });
  ok(resubmit.status === 200 && resubmit.json.item.status === 'pending', '驳回后修改并重新提交');
  const detail = await api('GET', `/api/reimbursements/${id2}`, { token: wToken });
  const acts = detail.json.item.history.map(h => h.action);
  ok(acts.includes('reject') && acts.includes('resubmit') && acts.includes('note'), '审批历史完整');

  const created3 = await api('POST', '/api/reimbursements', { token: lToken, body: { amount: 30.5, invoiceContent: '打车', reason: '加班回家', invoiceImage: PNG } });
  const id3 = created3.json.item.id;
  const withdraw = await api('POST', `/api/reimbursements/${id3}/withdraw`, { token: lToken });
  ok(withdraw.status === 200 && withdraw.json.item.status === 'withdrawn', '员工可撤回待审核申请');
  const withdrawAgain = await api('POST', `/api/reimbursements/${id3}/withdraw`, { token: lToken });
  ok(withdrawAgain.status === 400, '重复撤回被拒绝');
  const approveWithdrawn = await api('POST', `/api/reimbursements/${id3}/approve`, { token: fToken });
  ok(approveWithdrawn.status === 400, '已撤回申请不可审核');

  console.log('\n结果:', pass, '通过,', fail, '失败');
  process.exit(fail ? 1 : 0);
})().catch(e => { console.error('运行错误', e); process.exit(1); });
