  --gray: #8a93a6;  --gray-ink: #59637a;  --gray-soft: #eef1f5;
  --shadow: 0 1px 2px rgba(28,36,56,.05), 0 6px 22px rgba(28,36,56,.06);
  --shadow-lg: 0 8px 40px rgba(28,36,56,.18);
  --radius: 14px;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", "Helvetica Neue", sans-serif;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body { font-family: var(--font); background: var(--bg); color: var(--ink); font-size: 15px; line-height: 1.55; -webkit-font-smoothing: antialiased; }
[hidden] { display: none !important; }
button { font-family: inherit; cursor: pointer; }
input, textarea, select { font-family: inherit; font-size: 14px; color: var(--ink); }
::selection { background: var(--primary-2); color: #fff; }
a { color: var(--primary); text-decoration: none; }

/* ---------- 登录页 ---------- */
.login-wrap { min-height: 100vh; display: grid; grid-template-columns: 1.1fr 1fr; align-items: stretch; }
.login-brand { position: relative; overflow: hidden; background: linear-gradient(150deg,#3d54ff 0%, #6a4dff 55%, #9d4dff 100%); color: #fff; padding: 60px 54px; display: flex; flex-direction: column; justify-content: space-between; }
.login-brand::before, .login-brand::after { content: ""; position: absolute; border-radius: 50%; background: rgba(255,255,255,.10); }
.login-brand::before { width: 420px; height: 420px; top: -140px; right: -120px; }
.login-brand::after { width: 280px; height: 280px; bottom: -120px; left: -80px; }
.login-brand .logo { display: inline-flex; align-items: center; gap: 12px; font-size: 22px; font-weight: 800; letter-spacing: .3px; }
.login-brand .logo .mark { width: 42px; height: 42px; border-radius: 12px; background: rgba(255,255,255,.2); backdrop-filter: blur(4px); display: grid; place-items: center; }
.login-brand h1 { font-size: 34px; line-height: 1.25; margin: 18px 0 10px; font-weight: 800; }
.login-brand p { opacity: .9; max-width: 420px; }
.login-brand .features { display: grid; gap: 12px; margin-top: 20px; }
.login-brand .features div { display: flex; align-items: center; gap: 12px; background: rgba(255,255,255,.12); padding: 12px 16px; border-radius: 12px; backdrop-filter: blur(4px); font-size: 14px; }
.login-brand .features .dot { width: 8px; height: 8px; border-radius: 50%; background: #b7ffb7; box-shadow: 0 0 0 4px rgba(183,255,183,.2); }
.login-side { display: flex; align-items: center; justify-content: center; padding: 40px 24px; }
.login-card { width: 100%; max-width: 400px; }
.login-card h2 { margin: 0 0 6px; font-size: 24px; font-weight: 800; }
.login-card .sub { color: var(--ink-soft); margin: 0 0 24px; }
.field { margin-bottom: 16px; }
.field label { display: block; font-size: 13px; font-weight: 600; color: var(--ink-soft); margin-bottom: 6px; }
.field input, .field textarea, .field select {
  width: 100%; padding: 12px 14px; border: 1.5px solid var(--line); border-radius: 10px; background: #fff; outline: none; transition: .15s;
}
.field input:focus, .field textarea:focus, .field select:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(79,107,255,.15); }
.field .hint { font-size: 12px; color: var(--ink-faint); margin-top: 5px; }
.field.error input { border-color: var(--red); }
.field .err { color: var(--red-ink); font-size: 12px; margin-top: 5px; min-height: 16px; }
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; border: 1px solid transparent; border-radius: 10px; padding: 11px 18px; font-size: 14px; font-weight: 600; transition: .15s; }
.btn.primary { background: var(--primary); color: #fff; }
.btn.primary:hover { background: var(--primary-ink); }
.btn.subtle { background: var(--primary-soft); color: var(--primary-ink); border-color: transparent; }
.btn.subtle:hover { background: #e0e6ff; }
.btn.ghost { background: #fff; color: var(--ink-soft); border-color: var(--line); }
.btn.ghost:hover { border-color: var(--primary); color: var(--primary-ink); }
.btn.danger { background: var(--red-soft); color: var(--red-ink); }
.btn.danger:hover { background: #fbdcdd; }
.btn.success { background: var(--green-soft); color: var(--green-ink); }
.btn.success:hover { background: #d7f3e6; }
.btn:disabled { opacity: .5; cursor: not-allowed; }
.btn-block { width: 100%; }
.btn-sm { padding: 7px 12px; font-size: 13px; border-radius: 8px; }
.demo-accounts { margin-top: 22px; border-top: 1px dashed var(--line); padding-top: 16px; }
.demo-accounts .t { font-size: 12px; color: var(--ink-faint); margin-bottom: 8px; font-weight: 600; }
.demo-accounts .row { display: flex; flex-wrap: wrap; gap: 8px; }
.demo-accounts .p { font-size: 12.5px; padding: 6px 10px; border: 1px solid var(--line); border-radius: 8px; background: #fbfcff; color: var(--ink-soft); cursor: pointer; transition: .15s; }
.demo-accounts .p:hover { border-color: var(--primary); color: var(--primary-ink); background: var(--primary-soft); }

/* ---------- 应用壳 ---------- */
.shell { min-height: 100vh; }
.topbar { position: sticky; top: 0; z-index: 20; background: rgba(255,255,255,.85); backdrop-filter: blur(10px); border-bottom: 1px solid var(--line); }
.topbar-inner { max-width: 1120px; margin: 0 auto; padding: 12px 24px; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 18px; }
.brand .mark { width: 32px; height: 32px; border-radius: 9px; background: linear-gradient(135deg,var(--primary),#9d4dff); color: #fff; display: grid; place-items: center; font-size: 17px; }
.topbar-right { display: flex; align-items: center; gap: 14px; }
.user-chip { display: flex; align-items: center; gap: 10px; }
.user-chip .avatar { width: 34px; height: 34px; border-radius: 50%; background: var(--primary-soft); color: var(--primary-ink); display: grid; place-items: center; font-weight: 700; }
.user-chip .meta { line-height: 1.2; }
.user-chip .name { font-weight: 700; font-size: 14px; }
.role-badge { font-size: 11px; font-weight: 600; color: var(--primary-ink); background: var(--primary-soft); border-radius: 6px; padding: 1px 7px; }
.icon-btn { background: #fff; border: 1px solid var(--line); color: var(--ink-soft); border-radius: 9px; width: 34px; height: 34px; display: grid; place-items: center; }
.icon-btn:hover { border-color: var(--red); color: var(--red); }

.container { max-width: 1120px; margin: 0 auto; padding: 26px 24px 60px; }
.page-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; margin-bottom: 22px; flex-wrap: wrap; }
.page-head h2 { margin: 0 0 4px; font-size: 26px; font-weight: 800; }
.page-head .desc { color: var(--ink-soft); margin: 0; }

/* 统计卡片 */
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-bottom: 22px; }
.stat { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow); }
.stat .k { font-size: 12.5px; color: var(--ink-faint); font-weight: 600; }
.stat .v { font-size: 26px; font-weight: 800; margin-top: 4px; }
.stat .a { font-size: 12px; color: var(--ink-soft); margin-top: 2px; }
.stat.t-pending { border-top: 3px solid var(--amber); }
.stat.t-approved { border-top: 3px solid var(--blue); }
.stat.t-paid { border-top: 3px solid var(--green); }
.stat.t-rejected { border-top: 3px solid var(--red); }

/* 工具栏 */
.toolbar { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-bottom: 16px; flex-wrap: wrap; }
.tabs { display: flex; gap: 6px; background: #eef1f7; padding: 5px; border-radius: 12px; flex-wrap: wrap; }
.tab { border: none; background: transparent; padding: 7px 14px; border-radius: 8px; font-size: 13px; font-weight: 600; color: var(--ink-soft); transition: .15s; }
.tab:hover { color: var(--ink); }
.tab.active { background: #fff; color: var(--primary-ink); box-shadow: 0 1px 3px rgba(28,36,56,.12); }
.search { display: flex; align-items: center; gap: 8px; background: #fff; border: 1px solid var(--line); border-radius: 10px; padding: 8px 12px; }
.search input { border: none; outline: none; width: 170px; background: transparent; }

/* 申请卡片 */
.list { display: flex; flex-direction: column; gap: 12px; }
.reimb { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px; box-shadow: var(--shadow); display: grid; grid-template-columns: auto 1fr auto; gap: 16px; align-items: center; cursor: pointer; transition: .15s; }
.reimb:hover { border-color: var(--primary-2); box-shadow: var(--shadow-lg); transform: translateY(-1px); }
.reimb .thumb { width: 64px; height: 64px; border-radius: 10px; overflow: hidden; background: var(--gray-soft); display: grid; place-items: center; border: 1px solid var(--line); }
.reimb .thumb img { width: 100%; height: 100%; object-fit: cover; }
.reimb .thumb .ph { color: var(--ink-faint); font-size: 24px; }
.reimb .body { min-width: 0; }
.reimb .row1 { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.reimb .amount { font-size: 19px; font-weight: 800; color: var(--ink); }
.reimb .content { font-weight: 600; font-size: 14px; }
.reimb .reason { color: var(--ink-soft); font-size: 13px; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.reimb .meta { color: var(--ink-faint); font-size: 12px; margin-top: 6px; display: flex; gap: 12px; flex-wrap: wrap; }
.badge { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; font-weight: 700; border-radius: 999px; padding: 3px 10px; white-space: nowrap; }
.badge .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.badge.pending { background: var(--amber-soft); color: var(--amber-ink); }
.badge.approved { background: var(--blue-soft); color: var(--blue-ink); }
.badge.paid { background: var(--green-soft); color: var(--green-ink); }
.badge.rejected { background: var(--red-soft); color: var(--red-ink); }
.badge.withdrawn { background: var(--gray-soft); color: var(--gray-ink); }
.reimb .actions { display: flex; flex-direction: column; gap: 8px; align-items: stretch; }
.reimb .actions .btn { white-space: nowrap; }

.empty { text-align: center; padding: 60px 20px; color: var(--ink-faint); }
.empty .big { font-size: 44px; margin-bottom: 10px; }

/* ---------- 弹窗 ---------- */
.modal-layer { position: fixed; inset: 0; background: rgba(20,26,44,.45); backdrop-filter: blur(3px); display: flex; align-items: center; justify-content: center; padding: 24px; z-index: 50; }
.modal { background: #fff; border-radius: 18px; box-shadow: var(--shadow-lg); width: 100%; max-width: 560px; max-height: 90vh; overflow: auto; }
.modal-lg { max-width: 720px; }
.modal-head { position: sticky; top: 0; background: #fff; padding: 20px 24px 14px; border-bottom: 1px solid var(--line); display: flex; align-items: center; justify-content: space-between; }
.modal-head h3 { margin: 0; font-size: 18px; }
.modal-body { padding: 20px 24px 24px; }
.modal-foot { position: sticky; bottom: 0; background: #fff; padding: 14px 24px; border-top: 1px solid var(--line); display: flex; justify-content: flex-end; gap: 10px; flex-wrap: wrap; }
.close { border: none; background: var(--gray-soft); width: 32px; height: 32px; border-radius: 8px; display: grid; place-items: center; font-size: 16px; color: var(--ink-soft); }
.close:hover { background: var(--red-soft); color: var(--red); }

/* 详情 */
.detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 18px; }
.d-info { background: #f8f9fd; border-radius: 12px; padding: 12px 16px; }
.d-info .k { font-size: 12px; color: var(--ink-faint); }
.d-info .v { font-weight: 700; margin-top: 2px; font-size: 15px; }
.invoice-img { border: 1px solid var(--line); border-radius: 12px; overflow: hidden; background: var(--gray-soft); cursor: zoom-in; max-height: 320px; display: grid; place-items: center; }
.invoice-img img { width: 100%; max-height: 320px; object-fit: contain; display: block; }
.timeline { margin-top: 8px; }
.tl { position: relative; padding-left: 22px; }
.tl::before { content: ""; position: absolute; left: 7px; top: 4px; bottom: 4px; width: 2px; background: var(--line); }
.tl-item { position: relative; padding-bottom: 14px; }
.tl-item::before { content: ""; position: absolute; left: -19px; top: 4px; width: 11px; height: 11px; border-radius: 50%; background: #fff; border: 3px solid var(--primary); }
.tl-item.gray::before { border-color: var(--gray); }
.tl-item.red::before { border-color: var(--red); }
.tl-item.green::before { border-color: var(--green); }
.tl-item .t { font-weight: 700; font-size: 14px; }
.tl-item .m { color: var(--ink-soft); font-size: 13px; margin-top: 1px; }
.tl-item .time { color: var(--ink-faint); font-size: 12px; margin-top: 2px; }
.tl-item .note { margin-top: 6px; background: var(--red-soft); color: var(--red-ink); border-radius: 8px; padding: 8px 12px; font-size: 13px; }

/* 表单 */
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.form-grid .full { grid-column: 1 / -1; }
.upload-zone { border: 1.5px dashed var(--line); border-radius: 12px; padding: 20px; text-align: center; cursor: pointer; transition: .15s; }
.upload-zone.drag { border-color: var(--primary); background: var(--primary-soft); }
.upload-zone img.prev { max-height: 200px; max-width: 100%; border-radius: 8px; margin-top: 8px; }
.upload-zone .up-hint { color: var(--ink-faint); font-size: 13px; }
.upload-zone .u-ico { font-size: 30px; }
.dup-warn { background: var(--amber-soft); border: 1px solid #f6d39b; color: var(--amber-ink); border-radius: 10px; padding: 10px 14px; font-size: 13px; margin-top: 4px; }

/* Toast */
.toast-stack { position: fixed; top: 18px; right: 18px; z-index: 99; display: flex; flex-direction: column; gap: 10px; }
.toast { display: flex; align-items: center; gap: 10px; background: #fff; border-radius: 12px; padding: 12px 16px; box-shadow: var(--shadow-lg); border-left: 4px solid var(--primary); font-size: 13.5px; max-width: 340px; animation: slideIn .25s ease; }
.toast.success { border-left-color: var(--green); }
.toast.error { border-left-color: var(--red); }
.toast.info { border-left-color: var(--blue); }
.toast .t-ico { font-size: 17px; }
@keyframes slideIn { from { transform: translateX(120%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }

/* 图片查看器 */
.image-viewer { max-width: 90vw; max-height: 88vh; background: #fff; border-radius: 14px; overflow: hidden; position: relative; }
.image-viewer img { display: block; max-width: 100%; max-height: 88vh; }
.image-viewer .close { position: absolute; top: 10px; right: 10px; }

/* 加载占位 */
.skeleton { background: linear-gradient(90deg,#eef1f7,#f8f9fd,#eef1f7); background-size: 200% 100%; animation: shimmer 1.2s infinite; border-radius: 10px; height: 90px; }
@keyframes shimmer { to { background-position: -200% 0; } }

@media (max-width: 820px) {
  .login-wrap { grid-template-columns: 1fr; }
  .login-brand { display: none; }
  .stats { grid-template-columns: repeat(2,1fr); }
  .reimb { grid-template-columns: auto 1fr; }
  .reimb .actions { grid-column: 1 / -1; flex-direction: row; }
  .form-grid, .detail-grid { grid-template-columns: 1fr; }
}
