      <button class="btn ghost" onclick="closeModal('formModal')">取消</button>
      <button class="btn primary" id="saveBtn">${isEdit ? '保存并提交' : '提交申请'}</button>
    </div>
  `;
  $('#formModal').hidden = false;

  const zone = $('#uploadZone');
