}

function handleFile(file) {
  const mb = file.size / 1024 / 1024;
  if (!/^image\/(png|jpeg|jpg|gif|webp)/.test(file.type)) { setImageErr('请上传 PNG / JPG / GIF / WebP 图片'); return; }
