```
function makePng(w,h,rowFn){
  const zlib=require('node:zlib');
  const sig=Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]);
  const chunks=[];
  const ihdr=Buffer.alloc(13);
  ihdr.writeUInt32BE(w,0); ihdr.writeUInt32BE(h,4);
  ihdr[8]=8; ihdr[9]=2; ihdr[10]=0; ihdr[11]=0; ihdr[12]=0;
  chunks.push(chunk('IHDR',ihdr));
  const raw=Buffer.alloc(h*(1+w*3));
  let o=0;
  for(let y=0;y<h;y++){ raw[o++]=0; for(let x=0;x<w;x++){ const c=rowFn(x,y); raw[o++]=c[0]; raw[o++]=c[1]; raw[o++]=c[2]; } }
  const idat=zlib.deflateSync(raw);
  chunks.push(chunk('IDAT',idat));
  chunks.push(chunk('IEND',Buffer.alloc(0)));
  return Buffer.concat([sig, ...chunks]);
}
function chunk(type,data){
  const len=Buffer.alloc(4); len.writeUInt32BE(data.length,0);
  const typeBuf=Buffer.from(type,'ascii');
  const c=Buffer.concat([typeBuf,data]);
  const crc=Buffer.alloc(4); crc.writeUInt32BE(crc32(c)>>>0,0);
  return Buffer.concat([len,typeBuf,data,crc]);
}
```
