{"command": "Write-Output "=== 端口 3300 ==="; Get-NetTCPConnection -LocalPort 3300 -State Listen -ErrorAction SilentlyContinue | Select-Object State,LocalAddress,LocalPort,OwningProcess
Write-Output "=== 健康检查 ==="; node -e "
const B='http://127.0.0.1:3300';
(async()=>{
  const login=await fetch(B+'/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:'finance',password:'123456'})}).then(r=>r.json());
  const me=await fetch(B+'/api/me',{headers:{Authorization:'Bearer '+login.token}}).then(r=>r.json());
