{"command": "Get-Process msedge -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Start-Sleep -Seconds 2
$e = "C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"
function Shot($html, $out) {
  for ($i=1; $i -le 6; $i++) {
    $prof = "D:\manage project\.ep_" + (Get-Random)
    Remove-Item -Recurse -Force -ErrorAction SilentlyContinue $out
    & $e --headless=new --disable-gpu --no-first-run --user-data-dir="$prof" --window-size=800,600 --default-background-color=FFFFFFFF --screenshot="$out" "file:///$html" 2>$null
    Remove-Item -Recurse -Force -ErrorAction SilentlyContinue $prof
    Start-Sleep -Milliseconds 900
    if (Test-Path $out) { return $true }
  }
  return $false
}
$d = "D:\manage project\demo-invoices"
Write-Output ("inv1 => " + (Shot "$d\invoice-1-travel.html" "$d\invoice-1-travel.png"))
Write-Output ("inv2 => " + (Shot "$d\invoice-2-office.html" "$d\invoice-2-office.png"))
Get-ChildItem "$d" | Select-Object Name, Length", "description": "Render both invoice HTML templates to PNG", "workdir": "D:\manage project"}

