route('POST', '/api/admin/users', async (req) => {
  const admin = requireAdmin(req);
  const body = await readBody(req);
  const username = String(body.username||'').trim();
  const name = String(body.name||'').trim();
  const role = String(body.role||'employee').trim();
  const password = String(body.password||'');
  if (!username || username.length < 3) throw new HttpError(400,'用户名至少 3 位');
  if (!/^[a-zA-Z0-9_.-]+$/.test(username)) throw new HttpError(400,'用户名只能含字母/数字/._-');
  if (!name) throw new HttpError(400,'请输入姓名');
  if (!['employee','finance','cashier','admin'].includes(role)) throw new HttpError(400,'角色无效');
  if (password.length < 6) throw new HttpError(400,'密码至少 6 位');
  const exists = db.prepare('SELECT id FROM users WHERE username=?').get(username);
  if (exists) throw new HttpError(400,'用户名已存在');
  const salt = randomToken();
  const id = db.prepare('INSERT INTO users (username,password_hash,salt,name,role,active,created_at) VALUES (?,?,?,?,?,1,?)')
    .run(username, hashPassword(password,salt), salt, name, role, nowISO()).lastInsertRowid;
  logAudit('user_create', admin, username, `创建账号 ${name}(${role})`);
  return { item: publicUser(db.prepare('SELECT * FROM users WHERE id=?').get(id)) };
});
```

