route('PUT', '/api/admin/users/:id', async (req) => {
  const admin = requireAdmin(req);
  const target = db.prepare('SELECT * FROM users WHERE id=?').get(Number(req.params.id));
  if (!target) throw new HttpError(404,'账号不存在');
