  if (!['employee','finance','cashier','admin'].includes(role)) throw new HttpError(400,'角色无效');
  if (role !== 'admin') {
    if (target.role === 'admin' && activeAdminCount(target.id) <= 1) throw new HttpError(400,'至少保留一名启用的管理员');
  }
  if (target.id === admin.id && role !== 'admin') throw new HttpError(400,'不能改变当前登录账号的管理员角色');
  db.prepare('UPDATE users SET name=?, role=? WHERE id=?').run(name, role, target.id);
  logAudit('user_update', admin, target.username, `更新账号 ${target.username}：姓名=${name}，角色=${role}`);
  return { item: publicUser(db.prepare('SELECT * FROM users WHERE id=?').get(target.id)) };
});
