function openUserModal(id) {
  const isEdit = !!id;
  const u = id ? ACCT_USERS.find(x => x.id === id) : null;
  const roles = [['employee','员工'],['finance','财务审核'],['cashier','出纳'],['admin','管理员']];
  $('#userModalBody').innerHTML = `
    <div class="modal-head"><h3>${isEdit ? '编辑账号' : '新增账号'}</h3><button class="close" onclick="closeModal('userModal')">✕</button></div>
    <div class="modal-body">
      <div class="field" id="um_u"><label>账号（登录名）</label><input id="umUser" ${isEdit?'disabled':''} value="${esc(u?u.username:'')}" placeholder="字母/数字/_ . -" /><div class="err"></div></div>
      <div class="field" id="um_n"><label>姓名</label><input id="umName" value="${esc(u?u.name:'')}" placeholder="请输入姓名" /><div class="err"></div></div>
      <div class="field" id="um_r"><label>角色</label><select id="umRole">${roles.map(([v,l])=>`<option value="${v}" ${u&&u.role===v?'selected':''}>${l}</option>`).join('')}</select><div class="err"></div></div>
      ${isEdit ? '' : `
      <div class="field" id="um_p"><label>初始密码</label><input id="umPass" type="password" placeholder="至少 6 位" /><div class="err"></div></div>
      <div class="hint" style="color:var(--ink-faint);font-size:12px">账号创建后即可用该密码登录</div>`}
    </div>
    <div class="modal-foot"><button class="btn ghost" onclick="closeModal('userModal')">取消</button><button class="btn primary" id="umSave">${isEdit?'保存':'创建'}</button></div>
  `;
  $('#userModal').hidden = false;
  $('#umSave').addEventListener('click', async () => {
    const username = $('#umUser').value.trim(), name = $('#umName').value.trim(), role = $('#umRole').value;
    const password = $('#umPass') ? $('#umPass').value : '';
    let okE = true;
    setFieldErr('um_n', name ? '' : '请输入姓名'); if(!name) okE=false;
    if (isEdit) { setFieldErr('um_r',''); }
    else {
      setFieldErr('um_u', username.length>=3 && /^[A-Za-z0-9_.-]+$/.test(username) ? '' : '至少3位，仅限字母/数字/_ . -'); if(!(username.length>=3&&/^[A-Za-z0-9_.-]+$/.test(username))) okE=false;
      setFieldErr('um_p', password.length>=6 ? '' : '密码至少 6 位'); if(password.length<6) okE=false;
    }
    if(!okE) { toast('请完善信息', 'error'); return; }
    const btn=$('#umSave'); btn.disabled=true;
    const body = isEdit ? { name, role } : { username, name, role, password };
    const res = await api(isEdit?'PUT':'POST', isEdit?`/api/admin/users/${id}`:'/api/admin/users', body);
    btn.disabled=false;
    if(!res.ok){ toast(res.data.error||'保存失败','error'); return; }
