.skeleton { background: linear-gradient(90deg,#eef1f7,#f8f9fd,#eef1f7); background-size: 200% 100%; animation: shimmer 1.2s infinite; border-radius: 10px; height: 90px; }
@keyframes shimmer { to { background-position: -200% 0; } }

/* ---------- 管理后台 ---------- */
.muted { color: var(--ink-faint); }
.admin-nav { display: flex; gap: 6px; background: #eef1f7; padding: 5px; border-radius: 12px; margin-bottom: 18px; width: max-content; max-width: 100%; flex-wrap: wrap; }
.admin-tab { border: none; background: transparent; padding: 8px 18px; border-radius: 9px; font-size: 14px; font-weight: 600; color: var(--ink-soft); transition: .15s; }
.admin-tab:hover { color: var(--ink); }
.admin-tab.active { background: #fff; color: var(--primary-ink); box-shadow: 0 1px 3px rgba(28,36,56,.14); }

.acct-toolbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 12px; flex-wrap: wrap; }
.acct-count { color: var(--ink-soft); font-size: 14px; }
.acct-count b { color: var(--ink); }
.acct-table-wrap { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow); }
.acct-table { width: 100%; border-collapse: collapse; font-size: 14px; }
.acct-table th { text-align: left; padding: 12px 16px; background: #f8f9fd; color: var(--ink-soft); font-weight: 600; font-size: 13px; border-bottom: 1px solid var(--line); }
.acct-table td { padding: 12px 16px; border-bottom: 1px solid var(--line); vertical-align: middle; }
.acct-table tbody tr:last-child td { border-bottom: none; }
.acct-table tbody tr:hover { background: #fbfcff; }
.acct-ops { white-space: nowrap; text-align: right; display: flex; gap: 6px; justify-content: flex-end; }

.audit-bar { display: flex; gap: 10px; align-items: center; margin-bottom: 14px; flex-wrap: wrap; }
.audit-bar select { padding: 9px 12px; border: 1.5px solid var(--line); border-radius: 10px; background: #fff; outline: none; color: var(--ink); min-width: 150px; }
.audit-bar select:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(79,107,255,.15); }
.audit-list { display: flex; flex-direction: column; gap: 8px; }
.audit-item { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 12px 16px; display: grid; grid-template-columns: 140px 1fr; gap: 12px; box-shadow: var(--shadow); }
.audit-time { color: var(--ink-faint); font-size: 12.5px; padding-top: 2px; }
.audit-line { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.audit-detail { color: var(--ink-soft); font-size: 13px; margin-top: 4px; word-break: break-all; }

@media (max-width: 820px) {
  .login-wrap { grid-template-columns: 1fr; }
  .login-brand { display: none; }

