async function renderAdminChat() {
  const {ok, data} = await api('GET', '/api/admin/chat/config');
  const configured = ok && data.configured;
  const model = ok ? data.model : '';
  $('#adminBody').innerHTML = `
    <div class="chat-wrap">
      <div class="chat-panel">
        <div class="chat-head">
          <span class="chat-title">💬 智能问答</span>
          <span class="chat-meta">${configured ? '已连接 ' + model : '未配置 DeepSeek Key'}</span>
        </div>
        <div class="chat-body" id="chatBody"></div>
        ${configured ? `
        <div class="chat-input">
          <textarea id="chatInput" rows="2" placeholder="请问报销数据、系统运行情况…（Enter 发送，Shift+Enter 换行）"></textarea>
          <button class="btn primary" id="chatSend">发送</button>
        </div>` : `<div class="chat-empty">请在 config.json 的 deepseekApiKey（或环境变量 DEEPSEEK_API_KEY）填写 DeepSeek API Key 后重启服务，即可开始对话。</div>`}
      </div>
    </div>
  `;
  if (configured) {
    const body = $('#chatBody');
    const input = $('#chatInput');
    const send = $('#chatSend');
    const history = [];  // {role, content}
    function addMsg(role, text) {
      const div = document.createElement('div');
      div.className = 'chat-msg ' + (role === 'user' ? 'user' : 'bot');
      div.innerHTML = `<div class="chat-bubble">${esc(text)}</div>`;
      body.appendChild(div);
      body.scrollTop = body.scrollHeight;
    }
    const welcome = "您好，我是报销云管理员智能助手。可以问我：有多少待审核报销？最近谁做了什么操作？系统运行得怎么样？";
    addMsg('bot', welcome);
    function sendMsg() {
      const text = input.value.trim();
      if (!text) return;
      input.value = '';
      addMsg('user', text);
      history.push({ role: 'user', content: text });
      send.disabled = true;
      const loading = document.createElement('div');
      loading.className = 'chat-msg bot'; loading.innerHTML = `<div class="chat-bubble typing">思考中…</div>`;
      body.appendChild(loading); body.scrollTop = body.scrollHeight;
      api('POST', '/api/admin/chat', { messages: history })
        .then(({ok, data}) => {
          loading.remove();
          const reply = (data && data.reply) || (data && data.error) || '（无回复）';
          addMsg('bot', reply);
          history.push({ role: 'assistant', content: reply });
        })
        .catch(() => { loading.remove(); addMsg('bot', '请求失败，请稍后重试。'); })
        .finally(() => { send.disabled = false; input.focus(); });
    }
    send.addEventListener('click', sendMsg);
    input.addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMsg(); } });
    input.focus();
  }
}
