const B='http://127.0.0.1:3300';
const j=async(p,o)=>{const r=await fetch(B+p,o);let b={};try{b=await r.json()}catch{};return {s:r.status,b}};
(async()=>{
  const login=await j('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:'admin',password:'123456'})});
  const tok=login.b.token, H={Authorization:'Bearer '+tok};
  const cfg=await j('/api/admin/chat/config',{headers:H});
  console.log('chat/config configured=',cfg.b.configured,'model=',cfg.b.model,'baseUrl=',cfg.b.baseUrl);
  const chat=await j('/api/admin/chat',{method:'POST',headers:{...H,'Content-Type':'application/json'},body:JSON.stringify({messages:[{role:'user',content:'hi'}]})});
  console.log('chat(no key) status=',chat.s,'msg=',chat.b.error);
})().catch(e=>{console.error(e);process.exit(1)});
"", "description": "Verify final no-key config state", "workdir": "D:\manage project"}

