const fs = require('fs');
const B = 'http://127.0.0.1:3300';
const PNG = 'data:image/png;base64,' + fs.readFileSync('demo-invoices/invoice-1-travel.png').toString('base64');
let pass = 0, fail = 0;
const ok = (c, m) => { if (c) { pass++; console.log('  ✓', m); } else { fail++; console.log('  ✗ FAIL:', m); } };
const api = async (m, p, { token, body } = {}) => {
  const h = {};
  if (token) h['Authorization'] = 'Bearer ' + token;
  if (body !== undefined) h['Content-Type'] = 'application/json';
  const r = await fetch(B + p, { method: m, headers: h, body: body !== undefined ? JSON.stringify(body) : undefined });
  let j; try { j = await r.json(); } catch { j = {}; }
  return { s: r.status, j };
};
const login = async (u) => (await api('POST', '/api/login', { body: { username: u, password: '123456' } })).j.token;

(async () => {
  const z = await login('zhangwei'), f = await login('finance'), c = await login('cashier'), a = await login('admin');
  const reimb = async (t) => (await api('GET', '/api/reimbursements', { token: t })).j.items;
  const stats = async (t) => (await api('GET', '/api/stats', { token: t })).j;

  // 张伟提交 A
  const A = await api('POST', '/api/reimbursements', { token: z, body: { amount: 586, invoiceContent: '运输服务*客运服务费', reason: '赴上海出差高铁票', invoiceImage: PNG } });
  const idA = A.j.item.id;
  // 张伟提交 B 然后撤回
  const B2 = await api('POST', '/api/reimbursements', { token: z, body: { amount: 238.5, invoiceContent: '办公用品*打印纸', reason: '采购办公用纸', invoiceImage: PNG } });
  const idB = B2.j.item.id;
  await api('POST', `/api/reimbursements/${idB}/withdraw`, { token: z });

  console.log('== 张伟（本人，应见 A 与 B 两条）==');
  const zl = await reimb(z);
  ok(zl.some(x => x.id === idA) && zl.some(x => x.id === idB), '张伟能看到自己的 A 与 B');
  ok(zl.find(x => x.id === idB).status === 'withdrawn', '张伟能看到自己的已撤回 B');

  console.log('== 财务（不应见已撤回 B）==');
  const fl = await reimb(f);
  ok(fl.some(x => x.id === idA) && !fl.some(x => x.id === idB), '财务看不到已撤回 B');
  const fs2 = await stats(f);
  ok(fs2.total.n === 1 && fs2.withdrawn.n === 0, '财务统计排除已撤回');
  const fDetailB = await api('GET', `/api/reimbursements/${idB}`, { token: f });
  ok(fDetailB.s === 403, '财务直连已撤回详情被拒(403)');

  console.log('== 出纳（应看不到待审核 A，只对待打款/已打款可见）==');
  const cl = await reimb(c);
  ok(!cl.some(x => x.id === idA), '出纳看不到待审核 A');
  const cDetailA = await api('GET', `/api/reimbursements/${idA}`, { token: c });
  ok(cDetailA.s === 403, '出纳直连待审核详情被拒(403)');

  console.log('== 管理员（应见全部）==');
  const al = await reimb(a);
  ok(al.some(x => x.id === idA) && al.some(x => x.id === idB), '管理员可见全部(含已撤回)');

  console.log('== CSV（财务导出排除已撤回）==');
  const csv = await fetch(B + '/api/reimbursements.csv', { headers: { Authorization: 'Bearer ' + f } });
  const txt = await csv.text();
  ok(csv.status === 200 && txt.includes('运输服务') && !txt.includes('办公用品*打印纸'), '财务 CSV 不含已撤回');

  // 清理：删除张伟的两条，恢复空库
  await api('DELETE', `/api/admin/users/${ (await api('GET','/api/admin/users',{token:a})).j.items.find(u=>u.username==='zhangwei').id }`, { token: a }).catch?.(()=>{});
  // 直接清库更干净（下面 server 重启后 seedDemoData=false 不会重新注入）
  console.log('\n结果:', pass, '通过,', fail, '失败');
  process.exit(fail ? 1 : 0);
})().catch(e => { console.error('ERR', e); process.exit(1); });
