{"command": "node -e "
const fs=require('fs');const B='http://127.0.0.1:3300';
const PNG='data:image/png;base64,'+fs.readFileSync('demo-invoices/invoice-1-travel.png').toString('base64');
const j=async(p,o)=>{const r=await fetch(B+p,o);let b={};try{b=await r.json()}catch{};return {s:r.status,b,txt: await r.text().catch(()=> '')}};
(async()=>{
  // 登录 admin 创建一条（拿一张图）
  const admin=(await j('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:'admin',password:'123456'})})).b.token;
  const emp=(await j('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:'zhangwei',password:'123456'})})).b.token;
  const fin=(await j('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:'finance',password:'123456'})})).b.token;
  // 用张伟创建一条，拿 imageUrl
  const created=await j('/api/reimbursements',{method:'POST',headers:{Authorization:'Bearer '+emp,'Content-Type':'application/json'},body:JSON.stringify({amount:586,invoiceContent:'运输服务*客运服务费',reason:'赴上海出差',invoiceImage:PNG})});
  const imgUrl=created.b.item.imageUrl;
  console.log('created imageUrl:', imgUrl);
  // 无 token 访问
  const no=await fetch(B+imgUrl);
  console.log('image no-token status:', no.status);
  // 带 token 访问
  const withToken=await fetch(B+imgUrl+'?token='+emp);
  console.log('image with-token status:', withToken.status, 'ctype:', withToken.headers.get('content-type'));
  // 财务 CSV 接口应移除
  const finCsv=await fetch(B+'/api/reimbursements.csv',{headers:{Authorization:'Bearer '+fin}});
  console.log('finance csv status:', finCsv.status);
  // 管理员 CSV 仍可用
  const admCsv=await fetch(B+'/api/admin/reimbursements.csv',{headers:{Authorization:'Bearer '+admin}});
  console.log('admin csv status:', admCsv.status);
  // 越权：员工访问 admin csv
  const empCsv=await fetch(B+'/api/admin/reimbursements.csv',{headers:{Authorization:'Bearer '+emp}});
  console.log('employee admin-csv status:', empCsv.status);
})().catch(e=>{console.error(e);process.exit(1)});
"", "description": "Verify image auth and CSV route changes", "workdir": "D:\manage project"}

