{"command": "$env:GIT_TERMINAL_PROMPT=0
$in = "protocol=https`nhost=github.com`n`n"
$cred = ($in | git credential fill 2>$null)
$pass = ($cred | Select-String '^password=').Line -replace '^password=',''
$user = ($cred | Select-String '^username=').Line -replace '^username=',''
Write-Output "登录用户: $user"
$repoName = 'reimburse-system'
$body = @{ name=$repoName; private=$false; description='报销云 · 财务报销管理系统（可演示）'; auto_init=$false } | ConvertTo-Json
try {
  $resp = Invoke-RestMethod -Uri 'https://api.github.com/user/repos' -Method Post -Headers @{ Authorization=("Bearer " + $pass); 'User-Agent'='reimburse-setup'; 'Accept'='application/vnd.github+json' } -Body $body -ContentType 'application/json'
  Write-Output "REPO_CREATED: $($resp.full_name)"
  Write-Output ("CLONE_URL: " + $resp.clone_url)
} catch {
  Write-Output ("REPO_CREATE_FAILED: " + $_.Exception.Message)
}", "description": "Create a new public GitHub repository via API", "workdir": "D:\manage project"}

