{"command": "node -e "
const fs=require('fs');const z=require('node:zlib');
const src='C:\\Users\\Lenovo\\.dsh\\sessions\\--D-manage~0020project--\\session-1202f730-ee16-4be2-8e38-5d54e37aedc8\\session.jsonl.zstd';
const buf=z.zstdDecompressSync(fs.readFileSync(src));
let text=buf.toString('utf8');
// 脱敏（先替换已知具体密钥/令牌，再用正则兜底）
text=text.split('sk-REDACTED').join('sk-REDACTED');
text=text.split('gho_REDACTED').join('gho_REDACTED');
text=text.replace(/sk-[A-Za-z0-9]{10,}/g,'sk-REDACTED').replace(/gho_[A-Za-z0-9]{10,}/g,'gho_REDACTED');
text=text.replace(/Bearer [A-Za-z0-9._-]{20,}/g,'Bearer REDACTED');
text=text.replace(/\"(password_hash|salt)\":\"[^\"]*\"/g,'\"\$1\":\"REDACTED\"');
text=text.replace(/\"password\":\"[^\"]*\"/g,'\"password\":\"REDACTED\"');
console.log('总行数(近似):', text.split('\n').length);
const lines=text.split('\n').filter(Boolean);
for (let i=0;i<Math.min(3,lines.length);i++){ console.log('--- 第'+(i+1)+'行 ---'); console.log(lines[i].slice(0,600)); }
fs.writeFileSync('session-log.jsonl', text);
console.log('已写 session-log.jsonl, 字节:', Buffer.byteLength(text));
"", "description": "Decompress and sanitize session log, inspect schema", "workdir": "D:\manage project"}

