const fs = require('fs');
const z = require('node:zlib');
const src = 'C:\\Users\\Lenovo\\.dsh\\sessions\\--D-manage~0020project--\\session-1202f730-ee16-4be2-8e38-5d54e37aedc8\\session.jsonl.zstd';
const buf = fs.readFileSync(src);
// zstd 帧魔数：FD 2F B5 28 (小端) -> BA 5? 实际魔数为 0xFD2FB528, 文件头字节 28 B5 2F FD
const magic = Buffer.from([0x28, 0xB5, 0x2F, 0xFD]);
const idx = [];
for (let i = 0; i + 4 <= buf.length; i++) {
  if (buf[i] === magic[0] && buf[i+1] === magic[1] && buf[i+2] === magic[2] && buf[i+3] === magic[3]) idx.push(i);
}
console.log('检测到帧起始数:', idx.length, ' 位置:', idx.slice(0, 10));
// 逐帧解压
let total = Buffer.alloc(0);
for (let k = 0; k < idx.length; k++) {
  const start = idx[k];
  const end = (k + 1 < idx.length) ? idx[k + 1] : buf.length;
  const frame = buf.subarray(start, end);
  try {
    const out = z.zstdDecompressSync(frame);
    total = Buffer.concat([total, out]);
  } catch (e) {
    console.log('帧', k, '解压失败:', e.message, ' 帧大小', frame.length);
  }
}
console.log('解压总字节:', total.length, '  行数:', total.toString('utf8').split('\n').length);
", "file_path": "D:\manage project\build-log.js"}

