           .replace(/gho_[A-Za-z0-9]{10,}/g,'gho_REDACTED')
           .replace(/Bearer [A-Za-z0-9._-]{20,}/g,'Bearer REDACTED')
           .replace(/"(password_hash|salt|password|token)":"[^"]*"/g,'"$1":"REDACTED"');
const lines = text.split('\n').filter(Boolean);
// 统计事件类型
const types = {};
for (const l of lines) { try { const o = JSON.parse(l); const t = o.type || o.role || '?'; types[t]=(types[t]||0)+1; } catch { types['NONJSON']=(types['NONJSON']||0)+1; } }
