const fs = require('fs');
const z = require('node:zlib');
const src = 'C:\\Users\\Lenovo\\.dsh\\sessions\\--D-manage~0020project--\\session-1202f730-ee16-4be2-8e38-5d54e37aedc8\\session.jsonl.zstd';

function decompress(path) {
  const buf = fs.readFileSync(path);
  const magic = Buffer.from([0x28, 0xB5, 0x2F, 0xFD]);
  const idx = [];
  for (let i = 0; i + 4 <= buf.length; i++) if (buf[i]===magic[0]&&buf[i+1]===magic[1]&&buf[i+2]===magic[2]&&buf[i+3]===magic[3]) idx.push(i);
  let total = Buffer.alloc(0);
  for (let k = 0; k < idx.length; k++) {
    const start = idx[k], end = (k+1<idx.length)?idx[k+1]:buf.length;
    try { total = Buffer.concat([total, z.zstdDecompressSync(buf.subarray(start,end))]); } catch {}
  }
  return total.toString('utf8');
}
function sanitize(text) {
  text = text.split('sk-REDACTED').join('sk-REDACTED')
             .split('gho_REDACTED').join('gho_REDACTED');
  text = text.replace(/sk-[A-Za-z0-9]{10,}/g,'sk-REDACTED')
             .replace(/gho_[A-Za-z0-9]{10,}/g,'gho_REDACTED')
             .replace(/ghp_[A-Za-z0-9]{10,}/g,'ghp_REDACTED')
             .replace(/Bearer [A-Za-z0-9._-]{20,}/g,'Bearer REDACTED')
             .replace(/"(password_hash|salt|password|token|apiKey|access_token)":"[^"]*"/g,'"$1":"REDACTED"');
  return text;
}
function textOf(content) {
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) return content.map(b => (b && b.text) ? b.text : (typeof b === 'string' ? b : '')).join('\n');
  if (content && typeof content === 'object') return content.text || '';
  return '';
}

const raw = decompress(src);
const text = sanitize(raw);
fs.writeFileSync('session-log.jsonl', text);

// 可读转写（跳过流式 chunk/头部/元数据；工具调用只留一行说明）
const lines = text.split('\n').filter(Boolean);
const md = ['# 报销云项目 · 开发会话日志（脱敏）', '',
  '> 本文件由 DeepSeek Harness 会话日志导出并脱敏（密钥/令牌已替换为 REDACTED）。',
  '> 作者身份：使用本地 GitHub 账号 RBGZZ。', '',
  '> 完整事件流见 `session-log.jsonl`；本文件仅保留用户与助手对话、工具调用概览。', '',
  '---', ''];
let userCount = 0, asstCount = 0, toolCount = 0;
for (const l of lines) {
  let o; try { o = JSON.parse(l); } catch { continue; }
  const t = o.type;
  if (t === 'session') { md.push('会话 ID：`' + o.id + '`　工作目录：`' + o.cwd + '`　预设：`' + o.agentPreset + '`　创建时间：' + new Date(o.createdAt).toLocaleString('zh-CN')); md.push(''); }
  else if (t === 'user/message') { const c = textOf(o.content); if (c) { userCount++; md.push('## 👤 用户'); md.push(''); md.push(c); md.push(''); } }
  else if (t === 'assistant/message') { const c = textOf(o.content); if (c) { asstCount++; md.push('## 🤖 助手'); md.push(''); md.push(c); md.push(''); } }
  else if (t === 'tool/call') { const n = (o.name || o.data && o.data.name || 'tool'); const args = (o.arguments || o.data && o.data.arguments || ''); const a = typeof args === 'string' ? args.slice(0, 90) : JSON.stringify(args).slice(0, 90); toolCount++; md.push('> 🔧 [工具] ' + n + '(…' + a + ')'); md.push(''); }
}
md.splice(1, 0, '\n**统计**：用户消息 ' + userCount + ' 条 · 助手消息 ' + asstCount + ' 条 · 工具调用 ' + toolCount + ' 次。\n');
fs.writeFileSync('session-log.md', md.join('\n'));

// 校验：残留敏感值
const check = (s) => {
  const hits = (s.match(/sk-[A-Za-z0-9]{10,}/g) || []).concat(s.match(/gho_[A-Za-z0-9]{10,}/g) || []);
  return hits.length;
};
console.log('jsonl 大小:', Buffer.byteLength(text), '  行数:', lines.length);
console.log('md   大小:', Buffer.byteLength(md.join('\n')));
console.log('残留 sk-/gho_ 命中:', check(text));

